// that, a chain of setters produced a document with several of them present at
// once, which no FHIR server will accept and which nothing here reported.
func (b *DetectedIssueBuilder) SetIdentifiedPeriod(v Period) *DetectedIssueBuilder {
	b.clearIdentified()
	b.detectedIssue.IdentifiedPeriod = &v
	return b
}

// SetAuthor sets the Author field.
func (b *DetectedIssueBuilder) SetAuthor(v Reference) *DetectedIssueBuilder {
	b.detectedIssue.Author = &v
	return b
}

// AddImplicated adds a Implicated element.
func (b *DetectedIssueBuilder) AddImplicated(v Reference) *DetectedIssueBuilder {
	b.detectedIssue.Implicated = append(b.detectedIssue.Implicated, v)
	return b
}

// AddEvidence adds a Evidence element.
func (b *DetectedIssueBuilder) AddEvidence(v DetectedIssueEvidence) *DetectedIssueBuilder {
	b.detectedIssue.Evidence = append(b.detectedIssue.Evidence, v)
	return b
}

// SetDetail sets the Detail field.
func (b *DetectedIssueBuilder) SetDetail(v string) *DetectedIssueBuilder {
	b.detectedIssue.Detail = &v
	return b
}

// SetReference sets the Reference field.
func (b *DetectedIssueBuilder) SetReference(v string) *DetectedIssueBuilder {
	b.detectedIssue.Reference = &v
	return b
}

// AddMitigation adds a Mitigation element.
func (b *DetectedIssueBuilder) AddMitigation(v DetectedIssueMitigation) *DetectedIssueBuilder {
	b.detectedIssue.Mitigation = append(b.detectedIssue.Mitigation, v)
	return b
}

// clearIdentified unsets every variant of Identified[x], including the
// _field companions of the primitive ones.
func (b *DetectedIssueBuilder) clearIdentified() {
	b.detectedIssue.IdentifiedDateTime = nil
	b.detectedIssue.IdentifiedPeriod = nil
}
